"""ECG generated by the authors' weights, v1 and v2 for the same 8 s fragments as in subjects_raw.json.

The fragment is preprocessed exactly as an 8 s window in preprocess.py and generated as two 4 s halves,
as in evaluate.py. Output: a JSON with the processed PPG and ECG, the three generated ECG and heart rates.
Usage: sbatch gen_subjects.slurm --v1 runs/rddm_v1 --v2 runs/rddm_v2 --authors ../authors_weights
"""
import argparse
import json
import os
import warnings
from pathlib import Path

import numpy as np
import torch
from scipy.signal import butter, sosfiltfilt

from data import ROOT
from evaluate import CHUNK, ecg_bpm, load_authors
from preprocess import FILTER_ORDER, FS, LOADERS, process_window, resample, zscore
from sample_pairs import to_list
from train import generate_ecg, load_rddm


def processed_fragment(name, loader_args, start_s, seconds):
    # The same steps as preprocess.process_subject, then one window at start_s
    ecg, ecg_fs, ppg, ppg_fs = LOADERS[name][1](*loader_args)
    ecg, ppg = resample(np.asarray(ecg, float), ecg_fs), resample(np.asarray(ppg, float), ppg_fs)
    n = min(len(ecg), len(ppg))
    ecg = sosfiltfilt(butter(FILTER_ORDER, 0.5, "highpass", fs=FS, output="sos"), ecg[:n])
    ppg = sosfiltfilt(butter(FILTER_ORDER, [0.5, 8], "bandpass", fs=FS, output="sos"), ppg[:n])
    ecg, ppg = zscore(ecg), zscore(ppg)
    start, length = int(round(start_s * FS)), seconds * FS
    ecg_p, ppg_p, _ = process_window(ecg[start:start + length], ppg[start:start + length])
    return ecg_p.astype(np.float32), ppg_p.astype(np.float32)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--root", default=str(ROOT))
    parser.add_argument("--fragments", default="subjects_raw.json", help="output of sample_pairs.py --all")
    parser.add_argument("--authors", required=True, help="folder with the authors' .pth files")
    parser.add_argument("--v1", required=True, help="checkpoint directory of v1")
    parser.add_argument("--v2", required=True, help="checkpoint directory of v2")
    parser.add_argument("--epoch", type=int, default=499)
    parser.add_argument("--parts", nargs="*", default=["test"], help="add train to see the training subjects too")
    parser.add_argument("--seed", type=int, default=31)
    parser.add_argument("--out", default="subjects_generated.json")
    args = parser.parse_args()
    warnings.filterwarnings("ignore")
    device = "cuda" if torch.cuda.is_available() else "cpu"

    fragments = json.load(open(args.fragments))
    seconds = fragments["seconds"]
    assert (seconds * FS) % CHUNK == 0, "the fragment must split into 4 s halves"

    # Processed fragments first, so the models are loaded once
    jobs = []
    for name, rows in fragments["datasets"].items():
        listing = dict(LOADERS[name][0](Path(args.root)))
        for r in rows:
            if "error" in r or r["split"] not in args.parts:
                continue
            ecg, ppg = processed_fragment(name, listing[r["subject"]], r["start_s"], seconds)
            jobs.append({"dataset": name, "subject": r["subject"], "split": r["split"], "start_s": r["start_s"],
                         "ecg": ecg, "ppg": ppg})
        print(f"{name}: {sum(j['dataset'] == name for j in jobs)} fragments", flush=True)

    ppg = torch.from_numpy(np.stack([j["ppg"] for j in jobs]))[:, None].to(device)
    models = {
        "authors": load_authors(args.authors, device),
        "v1": load_rddm(args.v1, args.epoch, device),
        "v2": load_rddm(args.v2, args.epoch, device),
    }
    for key, model in models.items():
        torch.manual_seed(args.seed)
        halves = [generate_ecg(*model, h).cpu() for h in torch.split(ppg, CHUNK, dim=-1)]
        fake = torch.cat(halves, dim=-1).squeeze(1).numpy()
        for j, f in zip(jobs, fake):
            j[key] = f
        print(f"generated {key}", flush=True)

    result = {"fs": FS, "seconds": seconds, "models": list(models), "epoch": args.epoch, "datasets": {}}
    for j in jobs:
        row = {k: j[k] for k in ["subject", "split", "start_s"]}
        row["ppg"], row["ecg"] = to_list(j["ppg"]), to_list(j["ecg"])
        row["hr"] = {"real": round(ecg_bpm(j["ecg"].astype(float), clean=False), 1)}
        for key in models:
            row[key] = to_list(j[key])
            row["hr"][key] = round(ecg_bpm(j[key].astype(float), clean=True), 1)
        result["datasets"].setdefault(j["dataset"], []).append(row)

    with open(args.out, "w") as f:
        json.dump(result, f, separators=(",", ":"))
    print(f"saved {args.out}, {os.path.getsize(args.out) / 1e6:.1f} MB", flush=True)


if __name__ == "__main__":
    main()
